SET NAMES utf8mb4;

DROP TABLE IF EXISTS `areas_parceladas_regularizadas`;
CREATE TABLE `areas_parceladas_regularizadas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `municipio_id` varchar(60) DEFAULT NULL,
  `municipio` varchar(100) DEFAULT NULL,
  `num_matricula` varchar(50) DEFAULT NULL,
  `ano_aquisicao` varchar(10) DEFAULT NULL,
  `area_total_m2` varchar(50) DEFAULT NULL,
  `valor_imovel` varchar(200) DEFAULT NULL,
  `matricula_parcelamento` varchar(100) DEFAULT NULL,
  `registro_loteamento` text,
  `ocupacao` text,
  `descricao_area` text,
  `registro_propriedade` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_areas_parceladas_regularizadas_municipio_id` (`municipio_id`),
  CONSTRAINT `fk_areas_parceladas_regularizadas_municipio` FOREIGN KEY (`municipio_id`) REFERENCES `municipio`(`municipio_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

